// A visit stop is a physical viewpoint. Several narrative paragraphs can
// accompany it, while the afterword and bibliography have their own walls.
export function exhibitionVisitFocus(step) {
  if (!step) return 'entrance';
  if (step.kind === 'closing' || step.kind === 'citations') return step.kind;
  return `${step.roomIndex}/${step.stopIndex}`;
}

export function exhibitionAdjacentVisitStep(exhibition, index, direction = 1) {
  const steps = exhibition.steps;
  const focus = exhibitionVisitFocus(steps[index]);
  const delta = direction < 0 ? -1 : 1;
  let next = index + delta;
  while (next >= 0 && next < steps.length && exhibitionVisitFocus(steps[next]) === focus) next += delta;
  if (delta < 0 && next >= 0) {
    const previousFocus = exhibitionVisitFocus(steps[next]);
    while (next > 0 && exhibitionVisitFocus(steps[next - 1]) === previousFocus) next--;
  }
  return Math.max(-1, Math.min(steps.length, next));
}
